:root {
  --bg: #2b2d42;
  --card: #edf2f4;
  --ink: #2b2d42;
  --accent: #ef233c;
  --accent-dark: #d90429;
  --muted: #8d99ae;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--ink);
  padding: 16px;
}
.card {
  background: var(--card);
  width: 100%;
  max-width: 480px;
  padding: 24px;
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 var(--accent-dark);
  border-radius: 0;
}
h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
}
.stats {
  display: flex;
  gap: 24px;
  margin-bottom: 16px;
  font-size: 0.95rem;
  color: var(--muted);
}
.stats strong { color: var(--ink); }
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
#todo-input {
  flex: 1;
  min-width: 0;
  padding: 12px;
  font-size: 1rem;
  border: 3px solid var(--ink);
  background: #fff;
  color: var(--ink);
  border-radius: 0;
}
#todo-input:focus {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 16px;
  border: 3px solid var(--ink);
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.05s, transform 0.05s;
}
button:hover { background: var(--accent-dark); }
button:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; }
button:active { transform: translate(2px, 2px); }
.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.todo-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 3px solid var(--ink);
  background: #fff;
}
.todo-list li.completed .task-text {
  text-decoration: line-through;
  color: var(--muted);
}
.task-text { flex: 1; min-width: 0; word-break: break-word; }
.todo-list input[type="checkbox"] {
  width: 24px;
  height: 24px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
.todo-list input[type="checkbox"]:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.todo-list .delete-btn {
  padding: 4px 8px;
  font-size: 0.9rem;
  flex-shrink: 0;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  .input-row { flex-direction: column; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let tasks = [];
let nextId = 1;

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.completed).length;
}

function createTaskElement(task) {
  const li = document.createElement('li');
  li.id = 'todo-item-' + task.id;
  if (task.completed) li.classList.add('completed');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'todo-check-' + task.id;
  checkbox.checked = task.completed;
  checkbox.setAttribute('aria-label', 'Mark task complete: ' + task.text);
  checkbox.addEventListener('change', () => {
    task.completed = checkbox.checked;
    li.classList.toggle('completed', task.completed);
    updateCounts();
  });

  const span = document.createElement('span');
  span.className = 'task-text';
  span.id = 'todo-text-' + task.id;
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'delete-btn';
  del.id = 'todo-delete-' + task.id;
  del.textContent = 'Delete';
  del.setAttribute('aria-label', 'Delete task: ' + task.text);
  del.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, del);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, completed: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  updateCounts();
  input.value = '';
  input.focus();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    addTask();
  }
});

updateCounts();
